useMouse:
export function useMouse() {
  const x = ref(0);
  const y = ref(0);
  function update(e) { x.value = e.pageX; y.value = e.pageY; }
  onMounted(() => window.addEventListener('mousemove', update));
  onUnmounted(() => window.removeEventListener('mousemove', update));
  return { x, y };
}

useLocalStorage:
export function useLocalStorage(key, initial) {
  const value = ref(JSON.parse(localStorage.getItem(key)) ?? initial);
  watch(value, v => localStorage.setItem(key, JSON.stringify(v)));
  return value;
}

Composable Contracts:
export function useCounter(initial = 0) {
  const count = ref(initial);
  const increment = () => count.value++;
  const decrement = () => count.value--;
  const reset = () => count.value = initial;
  return { count: readonly(count), increment, decrement, reset };
}

